using System.ComponentModel.DataAnnotations;
using AITestHub.Entities.Enums;

namespace AITestHub.DTOs;

/// <summary>
/// A single executable API test case generated by the AI. In addition to the
/// manual test case fields it carries the HTTP request definition required by
/// the automated test executor.
/// </summary>
public class GeneratedApiTestCaseDto
{
    [Required(ErrorMessage = "Title is required.")]
    public string Title { get; set; } = string.Empty;

    [Required(ErrorMessage = "Description is required.")]
    public string Description { get; set; } = string.Empty;

    public string? Preconditions { get; set; }

    [Required(ErrorMessage = "Steps are required.")]
    public string Steps { get; set; } = string.Empty;

    [Required(ErrorMessage = "ExpectedResult is required.")]
    public string ExpectedResult { get; set; } = string.Empty;

    [Required(ErrorMessage = "Priority is required and must be a valid value (Low, Medium, High, Critical).")]
    public Priority? Priority { get; set; }

    [Required(ErrorMessage = "TestType is required and must be a valid value (Positive, Negative, EdgeCase).")]
    public TestType? TestType { get; set; }

    [Required(ErrorMessage = "HttpMethod is required.")]
    public string HttpMethod { get; set; } = string.Empty;

    [Required(ErrorMessage = "Endpoint is required.")]
    public string Endpoint { get; set; } = string.Empty;

    /// <summary>
    /// JSON request body. Must be null for GET and DELETE.
    /// </summary>
    public string? RequestBody { get; set; }

    [Range(100, 599, ErrorMessage = "ExpectedStatusCode must be a valid HTTP status code (100-599).")]
    public int ExpectedStatusCode { get; set; }
}
